class_name CTEngine
extends RefCounted
## FFT-faithful clocktick engine (Battle 1 slice). All integer math, no floats.
## Every tick each living unit gains CT equal to Speed; at CT >= ct_turn the unit
## takes its turn, then CT drops by ct_move_act / ct_act_only / ct_wait.
## Pure static helpers so the sim (BattleSim) and the forecast ribbon share one
## implementation.

static func ct_threshold(rules: Dictionary) -> int:
	return int(rules.get("ct_turn", 100))

static func ready_order(units: Array, ct: Dictionary, rules: Dictionary = {}) -> Array:
	## Returns ids of living units with CT >= threshold, sorted by CT desc, then Speed desc.
	var th: int = ct_threshold(rules)
	var ready: Array = []
	for u in units:
		if not bool(u.get("alive", true)):
			continue
		if int(ct.get(str(u["id"]), 0)) >= th:
			ready.append(str(u["id"]))
	ready.sort_custom(func(a: String, b: String) -> bool:
		var ca: int = int(ct.get(a, 0))
		var cb: int = int(ct.get(b, 0))
		if ca != cb:
			return ca > cb
		return _speed_of(units, a) > _speed_of(units, b))
	return ready

static func _speed_of(units: Array, id: String) -> int:
	for u in units:
		if str(u["id"]) == id:
			return int(u["speed"])
	return 0

static func step_to_ready(units: Array, ct: Dictionary, rules: Dictionary) -> Array:
	## Advances CT in place (each tick: CT += Speed for all living units) until at
	## least one unit is ready. Returns the ready ids in turn order.
	var th: int = ct_threshold(rules)
	var guard: int = 0
	while ready_order(units, ct, rules).is_empty() and guard < 10000:
		guard += 1
		for u in units:
			if bool(u.get("alive", true)):
				ct[str(u["id"])] = int(ct.get(str(u["id"]), 0)) + int(u["speed"])
	return ready_order(units, ct, rules)

static func forecast(units: Array, count: int, ct_start: Dictionary = {}, rules: Dictionary = {}) -> Array:
	## Non-mutating forecast of the next `count` unit names to act.
	var ct: Dictionary = {}
	for u in units:
		ct[str(u["id"])] = int(ct_start.get(str(u["id"]), 0))
	var names: Array = []
	var guard: int = 0
	while names.size() < count and guard < 1000:
		guard += 1
		var ready: Array = step_to_ready(units, ct, rules)
		for id in ready:
			var u: Dictionary = _unit_by_id(units, id)
			if u.is_empty():
				continue
			names.append(str(u["name"]))
			ct[id] = int(ct[id]) - int(rules.get("ct_move_act", 100))
			if names.size() >= count:
				break
	return names

static func _unit_by_id(units: Array, id: String) -> Dictionary:
	for u in units:
		if str(u["id"]) == id:
			return u
	return {}
